package ai.xzkj.recruitment.localconnector;
import ai.xzkj.recruitment.auth.*;import org.junit.jupiter.api.Test;import java.time.Instant;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.mock;
class LocalConnectorProductionApprovalTest{private final Instant now=Instant.parse("2026-08-30T12:00:00Z");private final SystemUser first=new SystemUser("first","hash","第一管理员",UserRole.RECRUITMENT_ADMIN),second=new SystemUser("second","hash","第二管理员",UserRole.RECRUITMENT_ADMIN);@Test void requiresTwoDifferentApprovers(){LocalConnectorProductionApproval x=approval();assertThatThrownBy(()->x.approve(first,24,now)).hasMessage("第二位批准人必须与申请人不同");x.approve(second,24,now);assertThat(x.active(now.plusSeconds(60))).isTrue();assertThat(x.getExpiresAt()).isEqualTo(now.plusSeconds(86400));}@Test void expiresWithoutAutomaticRenewal(){LocalConnectorProductionApproval x=approval();x.approve(second,1,now);x.expire(now.plusSeconds(3601));assertThat(x.getStatus()).isEqualTo("EXPIRED");assertThat(x.active(now.plusSeconds(3601))).isFalse();}@Test void revokeIsImmediate(){LocalConnectorProductionApproval x=approval();x.approve(second,24,now);x.revoke(first,"紧急停止",now.plusSeconds(1));assertThat(x.getStatus()).isEqualTo("REVOKED");assertThat(x.active(now.plusSeconds(2))).isFalse();}private LocalConnectorProductionApproval approval(){return new LocalConnectorProductionApproval(mock(BrowserDevice.class),"SEND_MESSAGE",1,3,first,"低配额试运行",now.minusSeconds(1));}}
